from __future__ import annotations

import ds.data
import polars as pl
from ds.data.paths import PARQUET_DIR
from ds.data.raw.char_ranking import CHAR_GROUP_DTYPE
from ds.data.raw.ultimateframedata import with_char_group


def test_char_group_id_has_one_type_in_every_table():
    """Polars SQL won't join an Enum key to a String one: the pick is one Enum everywhere"""
    schema = ds.data.init_db().schema()
    assert schema["char"]["char_group_id"] == CHAR_GROUP_DTYPE
    assert schema["char_ranking"]["char_group_id"] == CHAR_GROUP_DTYPE


def test_the_roster_script_writes_that_type():
    chars = pl.read_parquet(PARQUET_DIR / "char.parquet")
    rebuilt = with_char_group(chars.drop("char_group_id"))
    assert rebuilt.schema["char_group_id"] == CHAR_GROUP_DTYPE
    assert rebuilt.equals(chars)


def test_ranking_joins_to_fighters_and_their_frame_data():
    """A query a user ran that failed (Nov 2026): a pick's ranked players and its nair.

    It failed on the join key: `char` named it `char_group` and stored it as text, while
    `char_ranking` has `char_group_id` as an Enum.
    """
    got = ds.data.init_db().sql("""
        SELECT r.rank, r.tag, r.player_id, c.name AS character, f.move, f.startup, f.activeframes,
               f.endlag, f.landinglag, f.basedamage, f.advantage, f.totalframes
        FROM char_ranking r
        JOIN char c ON c.char_group_id = r.char_group_id
        JOIN framedata f ON f.char_id = c.id
        WHERE LOWER(f.move) = 'nair'
        ORDER BY r.rank
        LIMIT 5
    """)
    assert got.columns == [
        "rank", "tag", "player_id", "character", "move", "startup", "activeframes", "endlag",
        "landinglag", "basedamage", "advantage", "totalframes",
    ]  # fmt: skip
    # it runs; it finds nothing, since framedata calls the move 'Neutral Air', not 'nair'
    assert got.height == 0


def test_that_query_with_the_moves_real_name_finds_rows():
    got = ds.data.init_db().sql("""
        SELECT r.rank, r.tag, c.name AS character, f.move, f.startup
        FROM char_ranking r
        JOIN char c ON c.char_group_id = r.char_group_id
        JOIN framedata f ON f.char_id = c.id
        WHERE LOWER(f.move) = 'neutral air'
        ORDER BY r.rank
        LIMIT 5
    """)
    assert got.height == 5
    assert got["rank"].to_list() == sorted(got["rank"].to_list())
    assert got["character"].null_count() == 0
